$change = function ($current, $previous) { if ((float) $previous === 0.0) return (float) $current > 0 ? 100 : 0; return round(((float) $current - (float) $previous) / (float) $previous * 100, 1); };
$reqChange = $change($today->requests, $yesterday->requests); $tokenChange = $change($today->input_tokens + $today->output_tokens, $yesterday->input_tokens + $yesterday->output_tokens); $costChange = $change($today->cost, $yesterday->cost); $errorRate = $today->requests ? round($today->errors / $today->requests * 100, 2) : 0; $previousErrorRate = $yesterday->requests ? round($yesterday->errors / $yesterday->requests * 100, 2) : 0; $reportedTotal = (int) $breakdown->reported + (int) $breakdown->estimated; $reportedRate = $reportedTotal ? round($breakdown->reported / $reportedTotal * 100, 1) : 0; $cacheBase = max(1, (int) $today->requests); $maxModel = max(1, (int) ($topModels->max('requests') ?? 1));
