<script>(function(){var el=document.getElementById('traffic-chart');if(!el)return;var d=JSON.parse(el.dataset.points||'[]'),svg=el.querySelector('svg'),w=720,h=260,l=38,r=12,t=15,b=28,max=Math.max(1,...d.map(x=>Math.max(x.today,x.yesterday))),uw=w-l-r,uh=h-t-b,coords=k=>d.map((x,i)=>({x:l+i*uw/23,y:t+uh-(x[k]/max*uh)})),path=c=>c.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' '),a=coords('today'),z=coords('yesterday'),html='';[0,.25,.5,.75,1].forEach(q=>{var y=t+uh*q;html+='<line class="ops-gridline" x1="'+l+'" y1="'+y+'" x2="'+(w-r)+'" y2="'+y+'"/><text class="ops-axis" x="'+(l-6)+'" y="'+(y+3)+'" text-anchor="end">'+Math.round(max*(1-q))+'</text>'});d.forEach((x,i)=>{if(i%3===0)html+='<text class="ops-axis" x="'+a[i].x+'" y="'+(h-7)+'" text-anchor="middle">'+x.label+'</text>'});html+='<path class="ops-line-yesterday" d="'+path(z)+'"/><path class="ops-line-today" d="'+path(a)+'"/>';a.forEach((p,i)=>html+='<circle class="ops-point" cx="'+p.x+'" cy="'+p.y+'" r="3"><title>'+d[i].label+': '+d[i].today+' request, '+d[i].errors+' error, '+d[i].tokens+' token</title></circle>');svg.innerHTML=html})();</script>
